package deposit.service;

import deposit.common.Json;
import deposit.common.ValueCodec;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.geotools.api.referencing.crs.CoordinateReferenceSystem;
import org.geotools.referencing.CRS;
import org.locationtech.jts.geom.Geometry;
import org.locationtech.jts.io.WKBWriter;

/** Small GeoPackage 1.3 writer backed by the pinned SQLite JDBC runtime. */
final class GeoPackageAdapter {
    record Output(Path path,String filename,long bytes,String checksum,List<Map<String,Object>> warnings,boolean warningsTruncated) {}
    private GeoPackageAdapter() {}
    static Map<String,Object> load(Path source,Path destination,Map<String,Object> options,Map<String,Object> typeMap,Map<String,Object> formats,String decimal,Runnable check)throws IOException {
        String layer=(String)options.get("layer"),geometryColumn=(String)options.get("geometryColumn");if(layer==null||layer.isBlank())throw new IOException("GeoPackage layer is required");
        try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+source.toAbsolutePath());Statement sql=db.createStatement()){
            try(ResultSet checkResult=sql.executeQuery("PRAGMA quick_check")){if(!checkResult.next()||!"ok".equalsIgnoreCase(checkResult.getString(1)))throw new IOException("GeoPackage integrity check failed");}
            String dataType=null;Integer contentSrid=null;try(PreparedStatement content=db.prepareStatement("SELECT data_type,srs_id FROM gpkg_contents WHERE table_name=?")){content.setString(1,layer);try(ResultSet result=content.executeQuery()){if(result.next()){dataType=result.getString(1);int value=result.getInt(2);contentSrid=result.wasNull()?null:value;}}}
            if(dataType==null||!Set.of("features","attributes","aspatial").contains(dataType))throw new IOException("Selected GeoPackage layer is unavailable");String registeredGeometry=null,geometryType=null;int registeredSrid=0,zFlag=0;
            if("features".equals(dataType)){try(PreparedStatement geometry=db.prepareStatement("SELECT column_name,geometry_type_name,srs_id,z FROM gpkg_geometry_columns WHERE table_name=?")){geometry.setString(1,layer);try(ResultSet result=geometry.executeQuery()){if(!result.next())throw new IOException("Feature layer has no geometry registration");registeredGeometry=result.getString(1);geometryType=result.getString(2);registeredSrid=result.getInt(3);zFlag=result.getInt(4);if(result.next())throw new IOException("Multiple geometry columns are not supported in one selected layer");}}if(!Objects.equals(contentSrid,registeredSrid))throw new IOException("Layer SRS differs from its geometry registration");try(PreparedStatement srs=db.prepareStatement("SELECT count(*) FROM gpkg_spatial_ref_sys WHERE srs_id=?")){srs.setInt(1,registeredSrid);try(ResultSet result=srs.executeQuery()){if(!result.next()||result.getInt(1)!=1)throw new IOException("Layer SRS definition is missing");}}if(geometryColumn==null||!geometryColumn.equals(registeredGeometry))throw new IOException("geometryColumn must select the registered layer geometry");}
            else if(geometryColumn!=null)throw new IOException("geometryColumn is forbidden for an attribute layer");
            var columns=new ArrayList<Map<String,Object>>();var names=new ArrayList<String>();try(ResultSet info=sql.executeQuery("PRAGMA table_info("+q(layer)+")")){while(info.next()){if(info.getInt("pk")!=0)continue;String name=info.getString("name");if("features".equals(dataType)&&name.equals(registeredGeometry)){names.add(name);columns.add(Json.map("name",name,"type","DGeometry"));}else{String type=typeMap.containsKey(name)?ValueCodec.type(typeMap.get(name)):"String";names.add(name);columns.add(Json.map("name",name,"type",type));}}}
            if(names.isEmpty())throw new IOException("Selected GeoPackage layer has no columns");Set<String> unique=new HashSet<>();for(String name:names)if(name.isBlank()||!unique.add(java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFC)))throw new IOException("Invalid or duplicate GeoPackage column name");for(String name:typeMap.keySet())if(!names.contains(name))throw new IOException("columnTypes names an unknown column");for(String name:formats.keySet())if(!names.contains(name))throw new IOException("dateFormats names an unknown column");
            List<Map<String,Object>> diagnostics=new ArrayList<>();long rowCount=0,errors=0;boolean valid=true;Files.createDirectories(destination.getParent());
            try(BufferedWriter output=Files.newBufferedWriter(destination,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);ResultSet rows=sql.executeQuery("SELECT * FROM "+q(layer)+" ORDER BY rowid")){
                output.write("{\"columns\":");output.write(Json.write(columns));output.write(",\"rows\":[");boolean first=true;
                while(rows.next()){check.run();rowCount++;Map<String,Object> values=new LinkedHashMap<>(),presence=new LinkedHashMap<>();for(String name:names){String type=(String)columns.stream().map(ValueCodec::map).filter(col->name.equals(col.get("name"))).findFirst().orElseThrow().get("type");Object raw=rows.getObject(name);presence.put(name,true);if(raw==null){values.put(name,null);continue;}try{Object parsed;if("DGeometry".equals(type)){if(!(raw instanceof byte[] blob))throw new IOException("Geometry column is not binary");parsed=decodeGeometry(blob,registeredSrid,geometryType,zFlag);}else{String text=raw instanceof byte[] bytes?Base64.getEncoder().encodeToString(bytes):raw.toString();parsed=TabularService.parseTableCell(type,text,decimal,formats.get(name));}values.put(name,parsed);}catch(Exception error){values.put(name,raw instanceof byte[]?"":raw.toString());valid=false;errors++;if(diagnostics.size()<1000)diagnostics.add(Json.map("severity","error","code","CELL_CONVERSION","rowId",Long.toString(rowCount),"column",name,"message","Cell cannot be parsed as "+type));}}
                    if(!first)output.write(',');first=false;output.write(Json.write(Json.map("rowId",Long.toString(rowCount),"values",values,"presence",presence)));}
                output.write("],\"rowCount\":");output.write(Long.toString(rowCount));output.write(",\"valid\":");output.write(Boolean.toString(valid));output.write(",\"diagnostics\":");output.write(Json.write(diagnostics));output.write(",\"diagnosticsTruncated\":");output.write(Boolean.toString(errors>diagnostics.size()));output.write('}');
            }
            return Json.map("columns",columns,"rowCount",rowCount,"valid",valid,"diagnostics",diagnostics,"diagnosticsTruncated",errors>diagnostics.size());
        }catch(SQLException e){throw new IOException("Invalid GeoPackage container",e);}
    }
    private static Map<String,Object> decodeGeometry(byte[] blob,int registeredSrid,String registeredType,int zFlag)throws IOException {
        try{if(blob.length<8||blob[0]!='G'||blob[1]!='P'||blob[2]!=0)throw new IOException("Invalid GeoPackage geometry header");int flags=Byte.toUnsignedInt(blob[3]);if((flags&0xe0)!=0)throw new IOException("Reserved GeoPackage geometry flags are set");int srs=ByteBuffer.wrap(blob,4,4).order((flags&1)!=0?ByteOrder.LITTLE_ENDIAN:ByteOrder.BIG_ENDIAN).getInt();if(srs!=registeredSrid)throw new IOException("Geometry SRS differs from layer registration");if((flags&16)!=0)throw new IOException("Empty GeoPackage geometry is unsupported");int envelope=(flags>>1)&7;int ordinates=switch(envelope){case 0->0;case 1->4;case 2,3->6;case 4->8;default->throw new IOException("Invalid GeoPackage geometry envelope");};int offset=8+ordinates*8;if(offset>=blob.length)throw new IOException("Truncated GeoPackage geometry");byte[] wkb=Arrays.copyOfRange(blob,offset,blob.length);Geometry geometry=new org.locationtech.jts.io.WKBReader().read(wkb);boolean hasZ=!Double.isNaN(geometry.getCoordinate().getZ());if(hasZ&&zFlag==0||!hasZ&&zFlag==1)throw new IOException("Geometry dimension differs from layer registration");if(registeredType!=null&&!"GEOMETRY".equalsIgnoreCase(registeredType)&&!registeredType.equalsIgnoreCase(geometry.getGeometryType()))throw new IOException("Geometry type differs from layer registration");String wkt=new org.locationtech.jts.io.WKTWriter(hasZ?3:2).write(geometry);Map<String,Object> normalized=deposit.common.GeometryCodec.fromWkt(wkt,(long)srs,null);return Json.map("wkt",normalized.get("wkt"),"srid",normalized.get("srid"),"verticalSrid",null,"axisOrder",normalized.get("axisOrder"),"dimensions",normalized.get("dimensions"));}catch(IOException e){throw e;}catch(Exception e){throw new IOException("Invalid GeoPackage geometry",e);}
    }
    static List<Output> write(Path table,List<?> columns,String filename,String layer,Path directory,Runnable check)throws IOException {
        var geometryColumns=new ArrayList<String>();var attributes=new ArrayList<Map<String,Object>>();var names=new HashSet<String>();
        for(Object raw:columns){Map<String,Object> column=ValueCodec.map(raw);String name=(String)column.get("name"),type=(String)column.get("type");String normalized=java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFC).toLowerCase(Locale.ROOT);if(name.isBlank()||!names.add(normalized))throw new IOException("Invalid or duplicate GeoPackage column name");if(type.equals("DGeometry")||type.equals("Point"))geometryColumns.add(name);else attributes.add(column);}
        if(!geometryColumns.isEmpty()&&(names.contains("geometry")||names.contains("_deposit_row_id")||names.contains("_deposit_geometry_field")))throw new IOException("GeoPackage feature output contains a reserved column name");
        if(layer.isBlank()||layer.codePoints().anyMatch(Character::isISOControl)||Set.of("gpkg_spatial_ref_sys","gpkg_contents","gpkg_geometry_columns","gpkg_extensions","gpkg_tile_matrix_set","gpkg_tile_matrix").contains(layer.toLowerCase(Locale.ROOT)))throw new IOException("Invalid GeoPackage layer name");Files.createDirectories(directory);
        var srids=new TreeSet<Integer>();var warnings=new LinkedHashMap<String,Map<String,Object>>();boolean[] warningsTruncated={false};if(geometryColumns.isEmpty())srids.add(0);else try(Json.ArrayReader rows=new Json.ArrayReader(table,"rows")){Map<String,Object> row;while((row=rows.next())!=null){check.run();Map<String,Object> values=ValueCodec.map(row.get("values"));for(String field:geometryColumns){Object raw=values.get(field);GeometryValue geometry=raw==null?null:toGeometry(raw);srids.add(geometry==null?-1:geometry.srid());if(geometry!=null&&geometry.vertical()!=null){Map<String,Object> warning=Json.map("severity","warning","code","VERTICAL_CRS_OMITTED","rowId",row.get("rowId"),"column",field,"message","GeoPackage output omits vertical CRS metadata; Z coordinates are preserved");String key=Json.write(warning);if(warnings.size()<1000)warnings.putIfAbsent(key,warning);else warningsTruncated[0]=true;}}}}
        if(srids.isEmpty())srids.add(-1);var results=new ArrayList<Output>();String stem=filename.substring(0,filename.length()-5);
        for(int srid:srids){String outputName=geometryColumns.isEmpty()?filename:stem+(srid<0?"_unknown":"_"+srid)+".gpkg";Path output=directory.resolve(UUID.randomUUID()+".gpkg");writePart(table,columns,attributes,geometryColumns,layer,srid,output,check);results.add(new Output(output,outputName,Files.size(output),sha256(output),List.copyOf(warnings.values()),warningsTruncated[0]));}
        return results;
    }
    private record GeometryValue(Geometry geometry,int srid,Long vertical) {}
    private static GeometryValue toGeometry(Object raw)throws IOException {try{Map<String,Object> value=ValueCodec.map(raw);String wkt;int srid;if(value.containsKey("wkt")){wkt=(String)value.get("wkt");Object code=value.get("srid");srid=code instanceof Number n&&n.intValue()>=0?n.intValue():-1;}else{List<?> coords=(List<?>)value.get("coordinates");String wktValue="POINT("+String.join(" ",coords.stream().map(Object::toString).toList())+")";var g=new org.locationtech.jts.io.WKTReader().read(wktValue);int pointSrid=((Number)value.get("srid")).intValue();return new GeometryValue(g,pointSrid<0?-1:pointSrid,null);}Geometry geometry=new org.locationtech.jts.io.WKTReader().read(wkt);return new GeometryValue(geometry,srid,value.get("verticalSrid") instanceof Number v?v.longValue():null);}catch(Exception e){throw new IOException("Invalid geometry value",e);}}
    private static void writePart(Path json,List<?> allColumns,List<Map<String,Object>> attributes,List<String> geometryColumns,String layer,int srid,Path destination,Runnable check)throws IOException {
        try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+destination.toAbsolutePath());Statement sql=db.createStatement()){
            sql.execute("PRAGMA application_id=1196437808");sql.execute("PRAGMA user_version=10300");sql.execute("PRAGMA foreign_keys=ON");
            sql.execute("CREATE TABLE gpkg_spatial_ref_sys (srs_name TEXT NOT NULL,srs_id INTEGER NOT NULL PRIMARY KEY,organization TEXT NOT NULL,organization_coordsys_id INTEGER NOT NULL,definition TEXT NOT NULL,description TEXT)");
            sql.execute("INSERT INTO gpkg_spatial_ref_sys VALUES ('Undefined Cartesian',-1,'NONE',-1,'undefined','')");sql.execute("INSERT INTO gpkg_spatial_ref_sys VALUES ('Undefined Geographic',0,'NONE',0,'undefined','')");
            if(srid>0){Srs definition=resolveSrs(srid);try(PreparedStatement put=db.prepareStatement("INSERT INTO gpkg_spatial_ref_sys VALUES (?,?,?,?,?,?)")){put.setString(1,definition.name());put.setInt(2,srid);put.setString(3,"EPSG");put.setInt(4,srid);put.setString(5,definition.definition());put.setString(6,"");put.executeUpdate();}}
            sql.execute("CREATE TABLE gpkg_contents (table_name TEXT NOT NULL PRIMARY KEY,data_type TEXT NOT NULL,identifier TEXT UNIQUE,description TEXT DEFAULT '',last_change TEXT NOT NULL,min_x DOUBLE,min_y DOUBLE,max_x DOUBLE,max_y DOUBLE,srs_id INTEGER,FOREIGN KEY (srs_id) REFERENCES gpkg_spatial_ref_sys(srs_id))");
            sql.execute("CREATE TABLE gpkg_geometry_columns (table_name TEXT NOT NULL,column_name TEXT NOT NULL,geometry_type_name TEXT NOT NULL,srs_id INTEGER NOT NULL,z TINYINT NOT NULL,m TINYINT NOT NULL,PRIMARY KEY (table_name,column_name),UNIQUE (table_name),FOREIGN KEY (srs_id) REFERENCES gpkg_spatial_ref_sys(srs_id))");
            boolean feature=!geometryColumns.isEmpty();String dataType=feature?"features":"attributes";int tableSrid=feature?srid:0;StringBuilder ddl=new StringBuilder("CREATE TABLE ").append(q(layer)).append(" (fid INTEGER PRIMARY KEY AUTOINCREMENT");for(Map<String,Object> a:attributes)ddl.append(',').append(q((String)a.get("name"))).append(' ').append(sqlType((String)a.get("type")));if(feature)ddl.append(",_deposit_row_id TEXT NOT NULL,_deposit_geometry_field TEXT NOT NULL,geometry BLOB");ddl.append(')');sql.execute(ddl.toString());
            try(PreparedStatement content=db.prepareStatement("INSERT INTO gpkg_contents(table_name,data_type,identifier,description,last_change,srs_id) VALUES(?,?,?,?,?,?)")){content.setString(1,layer);content.setString(2,dataType);content.setString(3,layer);content.setString(4,"");content.setString(5,Instant.now().toString());if(feature)content.setInt(6,tableSrid);else content.setNull(6,Types.INTEGER);content.executeUpdate();}
            if(feature)try(PreparedStatement geometry=db.prepareStatement("INSERT INTO gpkg_geometry_columns VALUES(?,?,?,?,?,?)")){geometry.setString(1,layer);geometry.setString(2,"geometry");geometry.setString(3,"GEOMETRY");geometry.setInt(4,tableSrid);geometry.setInt(5,2);geometry.setInt(6,0);geometry.executeUpdate();}
            var insertColumns=new ArrayList<String>();for(Map<String,Object> a:attributes)insertColumns.add(q((String)a.get("name")));if(feature){insertColumns.add(q("_deposit_row_id"));insertColumns.add(q("_deposit_geometry_field"));insertColumns.add(q("geometry"));}String insert="INSERT INTO "+q(layer)+" ("+String.join(",",insertColumns)+") VALUES("+String.join(",",Collections.nCopies(insertColumns.size(),"?"))+")";db.setAutoCommit(false);try(PreparedStatement put=db.prepareStatement(insert);Json.ArrayReader rows=new Json.ArrayReader(json,"rows")){Map<String,Object> row;while((row=rows.next())!=null){check.run();Map<String,Object> values=ValueCodec.map(row.get("values")),presence=ValueCodec.map(row.get("presence"));if(!feature){int p=1;for(Map<String,Object> a:attributes)bind(put,p++,a,values,presence);put.executeUpdate();continue;}for(String field:geometryColumns){Object raw=values.get(field);GeometryValue geometry=raw==null?null:toGeometry(raw);int category=geometry==null?-1:geometry.srid();if(category!=srid)continue;int p=1;for(Map<String,Object> a:attributes)bind(put,p++,a,values,presence);put.setString(p++,String.valueOf(row.get("rowId")));put.setString(p++,field);if(geometry==null)put.setNull(p,Types.BLOB);else put.setBytes(p,gpkgGeometry(geometry));put.executeUpdate();}}db.commit();}catch(RuntimeException|SQLException e){db.rollback();throw e;}
            db.setAutoCommit(true);try(ResultSet result=sql.executeQuery("PRAGMA integrity_check")){if(!result.next()||!"ok".equalsIgnoreCase(result.getString(1)))throw new IOException("GeoPackage integrity check failed");}
        }catch(SQLException e){throw new IOException("Unable to write GeoPackage",e);}
    }
    private static void bind(PreparedStatement put,int index,Map<String,Object> column,Map<String,Object> values,Map<String,Object> presence)throws SQLException {String name=(String)column.get("name"),type=(String)column.get("type");Object value=Boolean.TRUE.equals(presence.get(name))?values.get(name):null;if(value==null){put.setNull(index,Types.NULL);return;}switch(type){case "Integer"->put.setLong(index,((Number)value).longValue());case "Float"->put.setDouble(index,((Number)value).doubleValue());case "Boolean"->put.setInt(index,Boolean.TRUE.equals(value)?1:0);case "DResource"->throw new SQLException("DResource export is unavailable");default->put.setString(index,TabularService.exportText(type,value));}}
    private static byte[] gpkgGeometry(GeometryValue geometry)throws IOException {double z=geometry.geometry().getCoordinate().getZ();byte[] wkb=new WKBWriter(Double.isNaN(z)?2:3,1).write(geometry.geometry());ByteBuffer header=ByteBuffer.allocate(8).order(ByteOrder.LITTLE_ENDIAN);header.put((byte)'G').put((byte)'P').put((byte)0).put((byte)1).putInt(geometry.srid());byte[] bytes=new byte[8+wkb.length];System.arraycopy(header.array(),0,bytes,0,8);System.arraycopy(wkb,0,bytes,8,wkb.length);return bytes;}
    private static String sqlType(String type){return switch(type){case "Integer","Boolean"->"INTEGER";case "Float"->"REAL";default->"TEXT";};}
    private record Srs(String name,String definition) {}
    private static Srs resolveSrs(int srid)throws IOException {
        try{CoordinateReferenceSystem crs=CRS.decode("EPSG:"+srid,true);String definition=crs.toWKT();if(definition==null||definition.isBlank())throw new IOException("No GeoPackage SRS definition is available for EPSG:"+srid);return new Srs(crs.getName().getCode(),definition);}
        catch(IOException e){throw e;}catch(Exception e){throw new IOException("No GeoPackage SRS definition is available for EPSG:"+srid,e);}
    }
    private static String q(String name){return "\""+name.replace("\"","\"\"")+"\"";}
    private static String sha256(Path path)throws IOException{try(var in=Files.newInputStream(path)){var digest=java.security.MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>=0)if(n>0)digest.update(buffer,0,n);return HexFormat.of().formatHex(digest.digest());}catch(java.security.NoSuchAlgorithmException e){throw new AssertionError(e);}}
}
